// Builds src/icons.js: the small subset of Lucide icons the Hub uses, as SVG
// path data keyed by the Hub's own semantic names. The Hub renders them as
// inline <svg> markup on the server (no icon font, no requests, CSP-safe).
//
//   cd scripts/vendor && npm ci && node build-icons.mjs
//
// Lucide is ISC-licensed; the licence is copied to licenses/lucide-ISC.txt.

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { createRequire } from 'node:module';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.join(here, '..', '..');
const require = createRequire(import.meta.url);
const pkgDir = path.dirname(require.resolve('lucide-static/package.json'));
const version = JSON.parse(readFileSync(path.join(pkgDir, 'package.json'), 'utf8')).version;
const nodes = JSON.parse(readFileSync(path.join(pkgDir, 'icon-nodes.json'), 'utf8'));

// Hub name -> Lucide name. Add here, rebuild, commit.
const MAP = {
  start: 'house', klassen: 'users', apps: 'layout-grid', bauen: 'code-xml', verwaltung: 'shield-check',
  search: 'search', bell: 'bell', chevronRight: 'chevron-right', chevronLeft: 'chevron-left', chevronDown: 'chevron-down',
  arrowLeft: 'arrow-left', arrowRight: 'arrow-right', plus: 'plus', x: 'x', check: 'check', checkCircle: 'circle-check',
  clock: 'clock', alert: 'circle-exclamation-point', warning: 'triangle-exclamation-point', trash: 'trash', pencil: 'pencil',
  upload: 'upload', download: 'download', play: 'play', maximize: 'maximize', minimize: 'minimize', eye: 'eye',
  fileCode: 'file-code', folder: 'folder', file: 'file', qr: 'qr-code', copy: 'copy', link: 'link', logout: 'log-out',
  settings: 'settings', user: 'user', userPlus: 'user-plus', school: 'school', tasks: 'list-todo', listChecks: 'list-checks',
  message: 'message-square', star: 'star', heart: 'heart', trophy: 'trophy', medal: 'medal', chart: 'chart-column',
  calendar: 'calendar', archive: 'archive', undo: 'rotate-ccw', external: 'external-link', info: 'info',
  sliders: 'sliders-horizontal', sun: 'sun', moon: 'moon', monitor: 'monitor', type: 'type', book: 'book-open',
  sparkles: 'sparkles', terminal: 'terminal', compare: 'git-compare', lock: 'lock', megaphone: 'megaphone',
  database: 'database', hardDrive: 'hard-drive', activity: 'activity', funnel: 'funnel', more: 'ellipsis', menu: 'menu',
  send: 'send', flag: 'flag', layers: 'layers', zap: 'zap', gamepad: 'gamepad-2', help: 'circle-question-mark',
  mail: 'mail', inbox: 'inbox', refresh: 'refresh-cw', badgeCheck: 'badge-check', bookmark: 'bookmark',
  template: 'layout-template', save: 'save', panelLeft: 'panel-left', edit: 'square-pen', hash: 'hash', timer: 'timer',
  palette: 'palette', contrast: 'contrast', accessibility: 'accessibility', scroll: 'scroll-text', podium: 'podium',
  smartphone: 'smartphone', tablet: 'tablet', laptop: 'laptop',
};

const esc = (v) => String(v).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const out = {};
for (const [name, lucide] of Object.entries(MAP)) {
  const node = nodes[lucide];
  if (!node) throw new Error(`Lucide has no icon "${lucide}" (for "${name}")`);
  out[name] = node
    .map(([tag, attrs]) => `<${tag} ${Object.entries(attrs).map(([k, v]) => `${k}="${esc(v)}"`).join(' ')}/>`)
    .join('');
}

const header = `'use strict';
// Icons: a subset of Lucide ${version} (https://lucide.dev), ISC licence - see licenses/lucide-ISC.txt.
// GENERATED by scripts/vendor/build-icons.mjs - do not edit by hand.
// Values are SVG child elements (fixed data, never user input).
`;
writeFileSync(path.join(root, 'src', 'icons.js'), `${header}module.exports = ${JSON.stringify(out, null, 2)};\n`);
mkdirSync(path.join(root, 'licenses'), { recursive: true });
writeFileSync(path.join(root, 'licenses', 'lucide-ISC.txt'), readFileSync(path.join(pkgDir, 'LICENSE'), 'utf8'));
console.log(`src/icons.js: ${Object.keys(out).length} icons from lucide-static ${version}`);
